-- 087_rich_text_inline.sql — M5B inline rich text editing
-- Update core/text to rich inline mode

UPDATE block_definitions SET
    schema_json = '{"schemaVersion":1,"props":{"type":"object","required":["text"],"properties":{"text":{"type":"object","default":{"version":1,"content":[]},"required":["version","content"],"properties":{"version":{"type":"integer","enum":[1]},"content":{"type":"array","items":{"type":"object","required":["text"],"properties":{"text":{"type":"string"},"marks":{"type":"array","items":{"type":"object","required":["type"],"properties":{"type":{"type":"string","enum":["bold","italic","strike","code","link"]},"href":{"type":"string"}}}}}}}}}}},"settings":{"type":"object","properties":{"align":{"type":"string","enum":["left","center","right"],"default":"left"},"tone":{"type":"string","enum":["default","muted","primary"],"default":"default"},"size":{"type":"string","enum":["sm","md","lg"],"default":"md"},"maxWidth":{"type":"string","enum":["narrow","normal","wide","none"],"default":"none"}}},"children":{"mode":"none"},"editor":{"category":"text","icon":"text","summaryFields":["props.text"],"fields":{"props.text":{"label":"Text","control":"richtext","inline":true,"inlineMode":"rich","placeholder":"Start typing…"},"settings.align":{"label":"Alignment","control":"segmented","group":"Style"},"settings.tone":{"label":"Tone","control":"select","group":"Style"},"settings.size":{"label":"Size","control":"segmented","group":"Style"},"settings.maxWidth":{"label":"Max width","control":"segmented","group":"Layout"}}}}',
    updated_at = unixepoch()
WHERE namespace = 'core' AND name = 'text' AND version = 2;
